// Material Maker nodes in material shaders. A Material Maker node's output is generated by the port of Material Maker's
// generator (material_maker/mm_embed.c): each canvas the parser walks is mirrored as a Material Maker graph, our own
// nodes feeding Material Maker inputs become native generators. Material Maker evaluates inputs at other uvs ($in(uv'),
// blurs, warps, normal maps): our nodes are then parsed again in a scope where the built-ins they read are redeclared,
// tex_coord as that uv, bposition extrapolated along the surface (see mm_bridge_finalize).

#include "../global.h"
#include "../material_maker/mm.h"

typedef struct {
	ui_node_t_array_t *nodes; // The canvas
	mm_gen_t          *graph;
} mm_bridge_canvas_t;

// Built-ins our nodes read that a nested scope redeclares from copies made at the start of main
typedef struct {
	const char *name;
	const char *type;
	const char *redeclare; // %s: the uv
	bool        used;
} mm_bridge_builtin_t;

static mm_bridge_builtin_t mm_bridge_builtins[] = {
    {"bposition", "vec3", "vec3 bposition = mm_g_bposition + mm_g_jb * ((%s) - mm_g_uv0);", false},
    {"n", "vec3", "vec3 n = mm_g_n;", false},
    {"vvec", "vec3", "vec3 vvec = mm_g_vvec;", false},
    {"vvec_cam", "vec3", "vec3 vvec_cam = mm_g_vvec_cam;", false},
    {"dotnv", "float", "float dotnv = mm_g_dotnv;", false},
};
#define MM_BRIDGE_BUILTINS (sizeof(mm_bridge_builtins) / sizeof(mm_bridge_builtins[0]))

static struct {
	node_shader_t     *shader; // The shader being generated, the state is reset for another one
	bool               active;
	mm_mark_t          mark;
	mm_emitter_t      *emitter;
	mm_bridge_canvas_t canvases[32];
	i32                ncanvases;
	buffer_t           decl; // The shader's Material Maker declarations, one function entry
	bool               decl_init;
	i32                depth;   // Nested scopes (our nodes parsed at another uv)
	bool               emitted; // The declarations are in the shader
} mm_bridge;

#define MM_BRIDGE_KEY "// Material Maker"

static const char *mm_bridge_type(char *socket_type) {
	if (string_equals(socket_type, "VALUE")) {
		return "f";
	}
	if (string_equals(socket_type, "RGB") || string_equals(socket_type, "VECTOR")) {
		return "rgb";
	}
	if (string_equals(socket_type, "RGBA")) {
		return "rgba";
	}
	static const char *mm[][2] = {{"MM_SDF2D", "sdf2d"},   {"MM_SDF3D", "sdf3d"}, {"MM_SDF3DC", "sdf3dc"}, {"MM_TEX3D_GS", "tex3d_gs"},
	                              {"MM_TEX3D", "tex3d"},   {"MM_V4V4", "v4v4"},   {"MM_FILL", "fill"}};
	for (u32 i = 0; i < sizeof(mm) / sizeof(mm[0]); ++i) {
		if (string_equals(socket_type, (char *)mm[i][0])) {
			return mm[i][1];
		}
	}
	return "rgba";
}

static void mm_bridge_reset(void) {
	if (mm_bridge.active) {
		mm_arena_release(mm_bridge.mark);
	}
	mm_bridge.active    = true;
	mm_bridge.shader    = parser_material_shader;
	mm_bridge.mark      = mm_arena_mark();
	mm_bridge.ncanvases = 0;
	mm_bridge.depth     = 0;
	mm_bridge.emitted   = false;
	mm_reset_ids();
	mm_bridge.emitter = mm_emitter_new("constants.mm_zero");
	if (!mm_bridge.decl_init) {
		string_buffer_init(&mm_bridge.decl);
		mm_bridge.decl_init = true;
	}
	string_buffer_reset(&mm_bridge.decl);
	// Fragment stage only: node_shader_get puts function strings that mention dFdx in #ifdef FRAG
	string_buffer_append(&mm_bridge.decl, MM_BRIDGE_KEY " (fragment stage only, dFdx)\n");
	string_buffer_append(&mm_bridge.decl, "vec2 mm_g_uv0; vec3 mm_g_bposition; mat2x3 mm_g_jb; vec3 mm_g_n; vec3 mm_g_vvec; vec3 mm_g_vvec_cam; float mm_g_dotnv;\n");
	// What Material Maker's shader template declares around the generated code (buffer_compute.tres)
	string_buffer_append(&mm_bridge.decl, "const float PI = 3.14159265359;\nconst float TAU = 2.0*PI;\nconst float seed_variation = 0.0;\nconst float elapsed_time = 0.0;\n");
	string_buffer_append(&mm_bridge.decl, mm_shader_functions());
	string_buffer_append(&mm_bridge.decl, "\n");
	for (u32 i = 0; i < MM_BRIDGE_BUILTINS; ++i) {
		mm_bridge_builtins[i].used = false;
	}
	node_shader_add_constant(parser_material_shader, "float mm_zero", "_mm_zero");
}

static char *mm_bridge_name(const char *prefix, ui_node_t *n, i32 socket) {
	return socket < 0 ? string_tmp("%s%d", prefix, n->id) : string_tmp("%s%d_%d", prefix, n->id, socket);
}

static ui_node_t *mm_bridge_node(ui_node_t_array_t *nodes, i32 id) {
	for (i32 i = 0; i < nodes->length; ++i) {
		if (nodes->buffer[i]->id == id) {
			return nodes->buffer[i];
		}
	}
	return NULL;
}

static char *mm_bridge_literal(ui_node_socket_t *s);

// The Material Maker graph of the canvas the parser is in
static mm_gen_t *mm_bridge_graph(void) {
	ui_node_t_array_t *nodes = parser_material_nodes;
	for (i32 i = 0; i < mm_bridge.ncanvases; ++i) {
		if (mm_bridge.canvases[i].nodes == nodes) {
			return mm_bridge.canvases[i].graph;
		}
	}
	mm_gen_t *graph = mm_graph_new();
	for (i32 i = 0; i < nodes->length; ++i) {
		ui_node_t *n = nodes->buffer[i];
		if (mm_node_is(n)) {
			mm_graph_add_data(graph, mm_bridge_name("n", n, -1), mm_node_data(n));
		}
	}
	ui_node_link_t_array_t *links = parser_material_links;
	for (i32 i = 0; i < links->length; ++i) {
		ui_node_link_t *l  = links->buffer[i];
		ui_node_t      *to = mm_bridge_node(nodes, l->to_id);
		ui_node_t      *fr = mm_bridge_node(nodes, l->from_id);
		if (to == NULL || fr == NULL || !mm_node_is(to)) {
			continue;
		}
		char *to_name = string_copy(mm_bridge_name("n", to, -1));
		if (mm_node_is(fr)) {
			mm_graph_connect(graph, mm_bridge_name("n", fr, -1), l->from_socket, to_name, l->to_socket);
		}
		else { // Our node feeding a Material Maker input
			char *name = mm_bridge_name("x", fr, l->from_socket);
			if (mm_gen_child(graph, name) == NULL) {
				mm_graph_add_native(graph, name, fr, l->from_socket, mm_bridge_type(fr->outputs->buffer[l->from_socket]->type));
			}
			mm_graph_connect(graph, name, 0, to_name, l->to_socket);
		}
		free(to_name);
	}
	// Unlinked inputs whose default is a constant: the socket's value, as edited
	for (i32 i = 0; i < nodes->length; ++i) {
		ui_node_t *n = nodes->buffer[i];
		if (!mm_node_is(n)) {
			continue;
		}
		for (i32 k = 0; k < n->inputs->length; ++k) {
			if (parser_material_get_input_link(n->inputs->buffer[k]) != NULL || mm_node_input_expression(n, k) != NULL) {
				continue;
			}
			char *name = string_copy(mm_bridge_name("c", n, k));
			mm_graph_add_constant(graph, name, mm_bridge_type(n->inputs->buffer[k]->type), mm_bridge_literal(n->inputs->buffer[k]));
			mm_graph_connect(graph, name, 0, mm_bridge_name("n", n, -1), k);
			free(name);
		}
	}
	if (mm_bridge.ncanvases < 32) {
		mm_bridge.canvases[mm_bridge.ncanvases].nodes   = nodes;
		mm_bridge.canvases[mm_bridge.ncanvases++].graph = graph;
	}
	return graph;
}

static char *mm_bridge_literal(ui_node_socket_t *s) {
	f32_array_t *d = s->default_value;
	f32          v[4] = {0, 0, 0, 1};
	for (i32 i = 0; d != NULL && i < d->length && i < 4; ++i) {
		v[i] = d->buffer[i];
	}
	char *t = parser_material_socket_glsl_type(s->type);
	if (string_equals(t, "float")) {
		return string_tmp("%f", v[0]);
	}
	if (string_equals(t, "vec2")) {
		return string_tmp("vec2(%f, %f)", v[0], v[1]);
	}
	if (string_equals(t, "vec3")) {
		return string_tmp("vec3(%f, %f, %f)", v[0], v[1], v[2]);
	}
	return string_tmp("vec4(%f, %f, %f, %f)", v[0], v[1], v[2], v[3]);
}

static bool mm_bridge_uses(const char *code, const char *name) {
	size_t l = strlen(name);
	for (const char *p = strstr(code, name); p != NULL; p = strstr(p + 1, name)) {
		bool before = p == code || !(isalnum((unsigned char)p[-1]) || p[-1] == '_' || p[-1] == '.');
		bool after  = !(isalnum((unsigned char)p[l]) || p[l] == '_');
		if (before && after) {
			return true;
		}
	}
	return false;
}

// Our node's output for Material Maker, at uv
static mm_native_t mm_bridge_native(void *node, int output, const char *uv, bool main) {
	ui_node_t  *n  = node;
	mm_native_t rv = {NULL, NULL};
	if (output < 0) { // An unlinked input's value
		rv.value = mm_strdup(mm_bridge_literal(n->inputs->buffer[-output - 1]));
		return rv;
	}
	ui_node_link_t link = {.id = 99998, .from_id = n->id, .from_socket = output, .to_id = -1, .to_socket = -1};
	if (main && parser_material_capture == NULL && mm_bridge.depth == 0) {
		rv.value = mm_strdup(parser_material_write_result(&link));
		return rv;
	}
	// At another uv: parsed again in a scope of its own, results are not shared with the main scope
	buffer_t        b;
	buffer_t       *outer_capture = parser_material_capture;
	string_array_t *outer_parsed  = parser_material_parsed;
	string_buffer_init(&b);
	parser_material_capture = &b;
	parser_material_parsed  = any_array_create_from_raw((void *[]){}, 0);
	mm_bridge.depth++;
	mm_emitter_push(mm_bridge.emitter);
	char *res = mm_strdup(parser_material_write_result(&link));
	mm_emitter_pop(mm_bridge.emitter);
	mm_bridge.depth--;
	array_delete(parser_material_parsed);
	parser_material_parsed  = outer_parsed;
	parser_material_capture = outer_capture;
	char    *code = string_buffer_get(&b);
	mm_buf_t c    = {0};
	mm_buf_printf(&c, "vec2 tex_coord = (%s);\n", uv);
	for (u32 i = 0; i < MM_BRIDGE_BUILTINS; ++i) {
		if (mm_bridge_uses(code, mm_bridge_builtins[i].name)) {
			mm_bridge_builtins[i].used = true;
			mm_buf_printf(&c, mm_bridge_builtins[i].redeclare, uv);
			mm_buf_add(&c, "\n");
		}
	}
	mm_buf_add(&c, code);
	string_buffer_free(&b);
	rv.code  = mm_buf_get(&c);
	rv.value = res;
	return rv;
}

// A Material Maker node's output (parser_material_node_outputs)
char *mm_bridge_output(ui_node_t *node, ui_node_socket_t *socket) {
	if (!mm_bridge.active || mm_bridge.shader != parser_material_shader) {
		mm_bridge_reset();
	}
	mm_gen_t *graph = mm_bridge_graph();
	mm_gen_t *g     = mm_gen_child(graph, mm_bridge_name("n", node, -1));
	i32       out   = parser_material_socket_index(node, socket);
	if (g == NULL || out < 0) {
		return parser_material_socket_zero(socket->type);
	}
	mm_set_native_code(mm_bridge_native);
	mm_emit_mark_t mark = mm_emitter_mark(mm_bridge.emitter); // Undone when this emission is dropped
	if (mm_bridge.depth > 0) {
		mm_emitter_push(mm_bridge.emitter);
	}
	mm_emit_t e = mm_emit(mm_bridge.emitter, g, out, MM_MAIN_UV, mm_bridge_type(socket->type));
	if (mm_bridge.depth > 0) {
		mm_emitter_pop(mm_bridge.emitter);
	}
	if (e.needs_buffers) { // Rendered into textures (mm_buffers.c), bound under the names the code samples
		// Every texture of a shader is bound at once, past GPU_MAX_TEXTURES the backend's state overflows. A margin for
		// the textures the material's other nodes and the paint shader add after this.
		i32 new_textures = 0;
		for (i32 i = 0; i < e.nbuffers; ++i) {
			if (string_array_index_of(parser_material_shader->textures, string_tmp("%s_t", e.buffer_names[i])) < 0) {
				new_textures++;
			}
		}
		if (parser_material_shader->textures->length + new_textures > GPU_MAX_TEXTURES - 8) {
			iron_log("Material Maker: node %s samples too many buffers (%d textures)", node->name, parser_material_shader->textures->length + new_textures);
			mm_emitter_reset(mm_bridge.emitter, mark);
			return parser_material_socket_zero(socket->type);
		}
		i32       *pass = mm_alloc(sizeof(i32) * e.nbuffers);
		mm_plan_t *plan = mm_plan_buffers(e.buffer_gens, e.nbuffers, pass);
		if (plan->error != NULL) {
			iron_log("Material Maker: node %s, buffers not rendered: %s", node->name, plan->error);
			mm_emitter_reset(mm_bridge.emitter, mark);
			return parser_material_socket_zero(socket->type);
		}
		mm_buffers_render(plan);
		for (i32 i = 0; i < e.nbuffers; ++i) {
			char *link = pass[i] >= 0 ? mm_buffers_link(plan, pass[i]) : NULL;
			if (link == NULL) {
				iron_log("Material Maker: node %s, buffer %s not rendered", node->name, e.buffer_names[i]);
				mm_emitter_reset(mm_bridge.emitter, mark);
				return parser_material_socket_zero(socket->type);
			}
			char *tex = string_tmp("%s_t", e.buffer_names[i]);
			node_shader_add_texture(parser_material_shader, string_copy(tex), link);
			string_buffer_append(&mm_bridge.decl, string_tmp("#define %s sampler2D(%s_t, sampler_linear)\n", e.buffer_names[i], e.buffer_names[i]));
		}
	}
	string_buffer_append(&mm_bridge.decl, e.declarations);
	mm_bridge.emitted = true;
	any_map_t *fns     = parser_material_shader->functions;
	bool       present = false;
	for (i32 i = 0; i < fns->keys->length; ++i) { // Replaced in place: any_map_set would also take the key pointer
		if (fns->keys->buffer[i] != NULL && string_equals(fns->keys->buffer[i], MM_BRIDGE_KEY)) {
			free(fns->values->buffer[i]);
			fns->values->buffer[i] = string_copy(string_buffer_get(&mm_bridge.decl));
			present                = true;
			break;
		}
	}
	if (!present) {
		any_map_set(fns, string_copy(MM_BRIDGE_KEY), string_copy(string_buffer_get(&mm_bridge.decl)));
	}
	if (e.code != NULL && e.code[0] != 0) {
		parser_material_write(parser_material_shader, e.code);
	}
	char *value = e.value != NULL ? e.value : parser_material_socket_zero(socket->type);
	if (!string_equals((char *)e.type, (char *)mm_bridge_type(socket->type))) { // No conversion: a typed zero
		return parser_material_socket_zero(socket->type);
	}
	return string_tmp("%s", value);
}

// A parse starts (parser_material_parse): the state of the previous one goes, it is made again on first use
void mm_bridge_begin(void) {
	if (mm_bridge.active) {
		mm_arena_release(mm_bridge.mark);
		mm_bridge.active = false;
	}
}

// Copies of the built-ins nested scopes read, at the start of main after their declarations (parser_material_finalize)
void mm_bridge_finalize(node_shader_t *shader) {
	if (!mm_bridge.active || mm_bridge.shader != shader || !mm_bridge.emitted) {
		mm_bridge_begin();
		return;
	}
	node_shader_write_attrib_frag(shader, "mm_g_uv0 = tex_coord;");
	node_shader_write_attrib_frag(shader, "float _seed_variation_ = seed_variation; vec4 _controlled_variation_ = vec4(0.0);");
	if (mm_bridge_builtins[0].used) {
		node_shader_write_attrib_frag(shader, "mm_g_bposition = bposition;");
		// d(bposition)/d(uv) from the screen space derivatives of both
		node_shader_write_attrib_frag(shader, "{ vec2 mm_dx = dFdx(tex_coord); vec2 mm_dy = dFdy(tex_coord); float mm_det = mm_dx.x * mm_dy.y - mm_dy.x * mm_dx.y;"
		                                      " mm_g_jb = abs(mm_det) > 1e-14 ? mat2x3(dFdx(bposition), dFdy(bposition)) * (mat2(mm_dy.y, -mm_dx.y, -mm_dy.x, mm_dx.x) / mm_det) : mat2x3(0.0); }");
	}
	for (u32 i = 1; i < MM_BRIDGE_BUILTINS; ++i) {
		if (mm_bridge_builtins[i].used) {
			node_shader_write_attrib_frag(shader, string_tmp("mm_g_%s = %s;", mm_bridge_builtins[i].name, mm_bridge_builtins[i].name));
		}
	}
	mm_bridge_begin(); // Done with this shader: another one may get its address (make_mesh finalizes without parsing)
}

// Our nodes' built-ins used by nested scopes must be declared by parser_material_finalize: the flags are set while
// parsing, before it runs
void mm_bridge_request_builtins(node_shader_t *shader) {
	if (!mm_bridge.active || mm_bridge.shader != shader || !mm_bridge.emitted) {
		return;
	}
	if (mm_bridge_builtins[0].used) {
		shader->frag_bposition = true;
	}
	if (mm_bridge_builtins[1].used) {
		shader->frag_n = true;
	}
	if (mm_bridge_builtins[2].used) {
		shader->frag_vvec = true;
	}
	if (mm_bridge_builtins[3].used) {
		shader->frag_vvec_cam = true;
	}
	if (mm_bridge_builtins[4].used) {
		shader->frag_dotnv = true;
	}
}

// Image node files: Material Maker's own resources come as a file name, shipped in data/material_maker; others are paths
static uint8_t *mm_bridge_read(const char *path, size_t *size) {
	buffer_t *b = data_get_blob(strchr(path, '/') == NULL ? string_tmp("material_maker/%s", path) : (char *)path);
	if (b == NULL || b->length == 0) {
		return NULL;
	}
	uint8_t *d = malloc(b->length);
	memcpy(d, b->buffer, b->length);
	*size = b->length;
	return d;
}

// Replaces the registration's placeholder code generation of every Material Maker node type
void mm_bridge_init(void) {
	mm_buffers_init(); // The image node's file reader, the text node's font
	string_array_t *keys = map_keys(parser_material_node_outputs);
	for (i32 i = 0; i < keys->length; ++i) {
		if (starts_with(keys->buffer[i], "MM_")) {
			any_map_set(parser_material_node_outputs, keys->buffer[i], mm_bridge_output);
		}
	}
	array_free(keys);
	free(keys);
}
